const prisma = new PrismaClient().$extends({
  query: {
    $allModels: {
      $allOperations: {
        async $allOperations({ model, operation, args, query }) {
          const start = Date.now();
          const result = await query(args);
          console.log(`${model}.${operation} took ${Date.now() - start}ms`);
          return result;
        }
      }
    }
  }
});
